		'check_authority_status' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\CheckAuthorityStatusTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress authority-status batch over ContentStoreInterface (Proposal 164 section 164.152). This is the family member whose declared default was the actual one: include_history is false in the schema and empty() reads the same, stated in the source because three neighbours got it wrong in the same direction. WordPress declared edit_posts but the handler checked read, so read is the handler rule the port keeps. A country filter dropped registrations with continue, leaving a shorter results array and no trace of an id the caller supplied; the port lists them in skipped and counts requested. A missing id is an item with found false rather than a failed batch, and every item carries found so one shape iterates. Status history has no writer anywhere in the toolkit, so an unwritten key is an empty list instead of an empty string, and a host that populates _status_history gets its value back. More than 100 ids is refused rather than truncated.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryComplianceToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'check_availability' => array(
			'class' => 'Nvoos\Core\Tool\Calendar\CheckAvailabilityTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the pre-write availability probe (Proposal 164 section 164.83): three independently switchable checks — overlapping appointments, business hours and blocked ranges — reported as available, reasons and a per_system map carrying the conflict ids. Corrections: business hours were a weekday test only, so a 22:00 booking on an enabled Monday passed; the whole span must now sit inside the open-close window. The conflict query is the half-open start < new_end AND end > new_start, which also catches an appointment contained in the window. Times are read as UTC and validated, where WordPress accepted any strtotime expression. per_system keeps a single nvoos entry so clients that read the map still find it, and the declared edit_posts capability is now enforced.',
			'evidence' => 'lib/core/tests/Unit/Tool/CalendarAvailabilityToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'check_capability' => array(
			'class' => 'Nvoos\\Core\\Tool\\CheckCapabilityTool',
			'readiness' => 'ready',
			'probe' => 'call',
			'evidence' => 'docker/laravel/app-skeleton/tests/Feature/ToolsReadinessTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'check_document_expiry' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\CheckDocumentExpiryTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress document expiry scan over ContentStoreInterface (Proposal 164 section 164.153). Two corrections in the date arithmetic. An unreadable expiry became false minus the clock, so a document dated n/a was reported expired some fifty-five years ago with a day count the value does not support; the port keeps the verdict, reports days_to_expiry null and names the value. And the old arithmetic mixed a midnight with an instant, so a document that expired yesterday reported minus two after midday; the port compares two UTC calendar dates, so today is 0, yesterday is -1, and the number is stable from midnight to midnight. WordPress also sorted the overdue list descending against its own most-urgent-first comment; the port orders both lists ascending, with an unreadable date first because it is the case that needs a human. A document with no expiry date is not counted valid, which was true before and never said. warning_days is bounded to 1-365 and refused outside it rather than clamped.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryExpiryToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'check_eca_conflicts' => array(
			'class' => 'Nvoos\\Core\\Tool\\Classroom\\CheckEcaConflictsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Answers "would this slot collide?" before a write, over the same rows the timetable reads (Proposal 164 section 164.58): roster, teacher list and venue, with minute-range overlap from Schedule so touching slots are not conflicts. `exclude_eca_id` covers the edit case. It sees only what this runtime stores; a room booking held elsewhere is invisible, and the description says so.',
			'evidence' => 'lib/core/tests/Unit/Tool/EcaReadToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'check_exit_conditions' => array(
			'class' => 'Nvoos\\Core\\Tool\\Orchestration\\CheckExitConditionsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the dual-condition gate (Proposal 164 section 164.78): exit needs both the completion score at threshold and an explicit exit_signal, while max iterations, token budget, expiry and an open breaker force a guarded exit with a distinct reason. Pinned: force_check is accepted and inert, because the WordPress checks always run.',
			'evidence' => 'lib/core/tests/Unit/Tool/OrchestrationLoopToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'check_hs_code' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\CheckHsCodeTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress HS code checker over the tool base (Proposal 164 section 164.151). An invalid code was returned as WP_Error wp_mcp_ai_invalid_arguments while the sibling validator returned success with is_valid false, so one family gave two answers to the same question; the port returns the verdict in the envelope. A four digit code produced two errors because the length check and the chapter check ran independently, so the chapter rule is skipped for a code already rejected for length. The chapter 33 rule is a scope statement rather than a defect and the description says so. Dotted and spaced codes are accepted and echoed as supplied, an unknown heading inside chapter 33 falls back to the chapter description, hs_info always carries a subcodes map, and product_type_match is true when no product type is supplied.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryInciHsValidationTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'check_higgsfield_request' => array(
			'class' => 'Nvoos\\Core\\Tool\\CheckHiggsfieldRequestTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'evidence' => 'docker/laravel/app-skeleton/tests/Feature/SearchAndProviderToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => true ),
		),
		'check_product_compliance' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\CheckProductComplianceTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress product compliance check over ContentStoreInterface (Proposal 164 section 164.152): a country requirement query, the product documents, and the product ingredient list, scored. Third instance of the same fault class and the worst composition: check_documents and check_ingredients are declared true and read with empty, so the documented call ran nothing, reported compliance_score 0 beside status compliant, and called a product with nothing checked compliant. The port applies the declared defaults and adds checks_ran, defined as at least one requirement evaluated with a check enabled, because the synthetic no-restriction pass makes total_checks 1 on a country that configures nothing. WordPress skipped a mandatory ingredient restriction entirely when the product had no INCI list, so it appeared in neither passed nor issues; the port reports it as a warning naming what could not be verified. Requirement is_mandatory follows the stored value, and the writer that stores false for an omitted argument is recorded here because it makes a documented requirement unenforced; the reader cannot distinguish the two cases. Document matching stays the bidirectional case-insensitive substring WordPress used, since no key joins a requirement to a document.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryComplianceToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
