			'reason' => 'MediaWorkerVideo over the media-worker `POST /api/video/process` (operation `compress`) plus `GET /api/video/download`. Needs ffmpeg on the worker (`video_processing`); without it the tool answers `no_video_engine`. No quality argument: the route uses a fixed CRF 28.',
