			'reason' => 'Ports the WordPress add-on activation over CloudwaysClientInterface (Proposal 164 section 164.141). The identifier is reduced to a slug because that is what the API keys add-ons by. One correction: WordPress built its message with esc_html, which corrupts a value inside a JSON envelope; the port returns the identifier as given.',
