		'create_video_from_images' => array(
			'class' => 'Nvoos\\Core\\Tool\\CreateVideoFromImagesTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'MediaWorkerVideoComposition over `POST /api/video/compose` (operation `images`: `-loop 1 -t <seconds>` per still, each fitted with `force_original_aspect_ratio=decrease` and padded, then an `xfade` chain, a `zoompan` drift, or `concat=n:N:v=1:a=0`) then `GET /api/video/download`. `contain` rather than `cover` because cropping a photograph loses what someone chose to show. `fade` and `slide` place each cut at `offset_i = (d₁ + … + d_i) − i × T` (measured on ffmpeg 8.1.2: three 2 s stills with a 0.5 s transition are 5.000 s exactly); the overlap is a caller knob (`transition_duration`, 0.05–5 s, default 0.5 s) because the WordPress contract has no such field. `zoom` is the one enum value that is not a boundary: it drifts each still from 1.0 to 1.12 with `zoompan` `d=1` driven by `on` (the `zoom` accumulator restarts per input frame and never moves on a looped still), upscaling the branch first so the integer x/y steps do not shimmer, and leaves the joins as hard cuts — verified by frame-to-frame PSNR (7.27 dB where a still image would read `inf`) and by a 100-frame, 4.000 s result for two 2 s stills. `none` is the default: the WordPress tool defaults to `fade` and then does nothing, and a default that changes existing output costs more than one argument. There is no audio argument because the route reads one ordered file list.',
			'evidence' => 'docker/laravel/app-skeleton/tests/Feature/VideoCompositionAdapterTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
