		'crm_email_search_accounting' => array(
			'class' => 'Nvoos\Core\Tool\Crm\\CrmEmailSearchAccountingTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the accounting email search over ContentStoreInterface (Proposal 164 section 164.68): transaction type, billing status, service category, invoice-amount range, currency, domain, fiscal window, audit metadata and the financial summary. The transaction filter reads accounting_transaction_type, not the argument name. No writer sets any accounting key in the toolkit, but the defaults are benign (all/date), so a default call returns contacts with empty accounting fields while any non-all accounting filter finds nothing on a manager-written store. Fiscal quarters are calendar quarters, as the WordPress code hardcodes. days_overdue sorts the returned page only, as WordPress does; an unparsable due date yields null instead of WordPress 20,000-day coercion. get_cached is a not-found error on a miss, unlike the lead search. The default currency is the CRM setting; audit hints report no integration because the core cannot detect one.',
			'evidence' => 'lib/core/tests/Unit/Tool/CrmEmailSearchAccountingToolTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'crm_email_search_correspondence' => array(
			'class' => 'Nvoos\Core\Tool\Crm\\CrmEmailSearchCorrespondenceTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the correspondence search over ContentStoreInterface (Proposal 164 section 164.69): the five follow-up modes, category/channel/status filters, all-tags matching, SLA-breach filtering, relevance ranking, and per-contact analytics with routing. Two defaults collide, and both are pinned: needs_followup includes last_contacted NOT EXISTS, while the default last_contacted sort is a meta_key INNER JOIN that drops exactly those rows, so the default call sees only the stale half and never_contacted with the default sort returns zero. The channel filter reads the stored channel meta, so an absent channel does not match email even though the projection defaults to it. sla_breach_only does not treat a never-contacted record as a breach. Malformed dates yield null analytics and are never reported as a breach, a documented deviation. get_cached is a not-found error on a miss, and the native total is the pre-post-filter count, as WordPress returns it.',
			'evidence' => 'lib/core/tests/Unit/Tool/CrmEmailSearchCorrespondenceToolTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'crm_email_search_leads' => array(
			'class' => 'Nvoos\Core\Tool\Crm\\CrmEmailSearchLeadsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the lead email search over ContentStoreInterface (Proposal 164 section 164.67): the declared filter family (pipeline stage, inquiry type, source, priority, MQL stage, owner, score range, email domain, date range), the relevance order, and the cache actions. Two WordPress defaults return nothing on a store written only by manage_crm_contact, and both are pinned: lead_status defaults to new (a key the manager never writes) and orderby defaults to lead_score, which WordPress sorts through a meta_key INNER JOIN that excludes rows without the key. The working invocation is lead_status: all, orderby: date. Meta sorts and relevance fetch a bounded 500-row window and sort in memory because ContentQuery sorts on date, title and id only. Cache is an optional CacheStoreInterface; without it the payload reports cached: false. schedule, unschedule, import_from_gmail and include_external answer with typed *_unavailable errors because the core carries no cron or Gmail service.',
			'evidence' => 'lib/core/tests/Unit/Tool/CrmEmailSearchLeadsToolTest.php',
