			'reason' => 'Writes through the bound `MemoryStoreInterface` under wing `user/{agent_id}` and room `style` or `drafts`. The WordPress verbatim discipline is reproduced as two records — the exact text at `tier=archival`, an optional summary as the `tier=recall` representative — with the summary record written only after the original succeeds, because a summary without its original defeats the purpose. `subject_refs`, `attachments`, `recorded_at`, `valid_from`, `valid_until`, `sensitivity` and `consent_basis` travel in the `metadata` map added in §164.42, written only when supplied. `verbatim` is derived rather than accepted as a parameter: the archival record holds the original so it says true, a recall record holding a summary says false. `tier` is likewise derived, and `allow_summarisation` is absent because there is no model here to summarise with (Proposal 164 sections 164.41 and 164.43).',
