		'export_assistant_blueprint' => array(
			'class' => 'Nvoos\\Core\\Tool\\Orchestration\\ExportAssistantBlueprintTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the blueprint exporter (Proposal 164 section 164.81) over AssistantExportInterface, so the bundle shape and the credential denylist stay in the one engine export_assistant and the REST controller share. The canonical entry is renamed into the blueprint dialect (name, description, meta.instructions/available_tools/provider/model/temperature), reading both the short bundle keys and the WordPress-prefixed aliases; a missing excerpt becomes the first 40 words of the system prompt. save_to_media is honoured through FileStoreInterface and refused explicitly when no store is bound. Flags declare the write WordPress omitted while calling the tool read-only.',
			'evidence' => 'lib/core/tests/Unit/Tool/OrchestrationResearchToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => false ),
		),
		'export_calendar_ics' => array(
			'class' => 'Nvoos\Core\Tool\Calendar\ExportCalendarIcsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the project calendar export (Proposal 164 section 164.84). WordPress was broken three ways: it required the post type project although the toolkit writes mcp_ai_project, it collected tasks and events by post_parent and read _event_date, and it needed an unbound media worker route or filter to generate anything. The port reads _task_project_id and _event_project_id with the same date meta the writers store, and builds an RFC 5545 document in PHP with escaped text, 75-octet folding, UTC times and VALUE=DATE all-day entries, so no sidecar is needed. An event spanning the range is included via the overlap test. The file is stored through the file registry, private by default, and the response can return the content inline instead.',
			'evidence' => 'lib/core/tests/Unit/Tool/CalendarEventToolsTest.php',
