		'fnb_budget_variance' => array(
			'class' => 'Nvoos\\Core\\Tool\\Fnb\\FnbBudgetVarianceTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the budget-versus-actual comparison (M-20, Proposal 164 section 164.74). Rows are sorted by variance descending with an unrecorded actual last, which is the tool sorting the metric rather than the metric sorting itself. The WordPress is_wp_error() check on the result is dead because the engine answers an array with an error key rather than a WP_Error, so an unreadable budget sheet is an empty success; that is pinned, not corrected. source is the tool name because the WordPress tool overwrote the metric source.',
			'evidence' => 'lib/core/tests/Unit/Tool/FnbMetricWrapperToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'fnb_calculate_metric' => array(
			'class' => 'Nvoos\\Core\\Tool\\Fnb\\FnbCalculateMetricTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the metric dispatcher and the whole engine (Proposal 164 section 164.72): M-01 to M-21, the five block helpers (stock used, operating cost, payroll, utility meters and costed utilities, expense lines), M-13 dish share, M-19 unit price as of a date and menu engineering. The engine is an instance with an injected table source rather than the WordPress statics, and money is rounded to the tenant currency decimals (LKR/JPY/KRW/VND have none) as the tenant profile did. Errors travel inside a metric result and the dispatcher converts them to metric_error, so a nested metric still reports the figures it has. Unknown ids answer unknown_metric with the nearest valid id. Dish margins resolve the recipe cost from the menu, then the recipes, then supplier prices, and say which answered. as_of is read but undeclared in the schema, as in WordPress.',
			'evidence' => 'lib/core/tests/Unit/Tool/FnbMetricsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
