		'fnb_compare_periods' => array(
			'class' => 'Nvoos\\Core\\Tool\\Fnb\\FnbComparePeriodsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the month-on-month comparison (Proposal 164 section 164.72): ten metrics with absolute and percentage change, plus the Food and Beverage revenue split. A metric whose either month errors is dropped rather than reported as zero; the split rows are not error-checked, because the WordPress code reads value off a zeroed metric array, so an unreadable sales table yields two zero rows. This is why the adapter probe is a success on an unmapped corpus. Two deviations are recorded: the demo months 2026-09 against 2026-08 become this month against the previous one, and the split label carries the configured currency instead of a hardcoded LKR.',
			'evidence' => 'lib/core/tests/Unit/Tool/FnbMetricsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
