		'fnb_days_of_cover' => array(
			'class' => 'Nvoos\\Core\\Tool\\Fnb\\FnbDaysOfCoverTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports M-14 with the over-ordering flag (Proposal 164 section 164.73). The cap is the ingredient shelf life when the ingredients table has one and fourteen days otherwise, and the flag is a string (empty when inside the cap) because WordPress callers test truthiness. The shelf-life lookup is the first matching row and an unreadable ingredients table leaves it at zero rather than failing the call. as_of must be Y-m-d or the configured as-of date applies, which is what makes a report reproducible.',
