			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports M-21 as two shapes (Proposal 164 section 164.74): with item_id, one dish margin with menu price, recipe cost and cost percentage; without it, the Kasavana and Smith matrix over a month, with every item quadranted by popularity share and margin. A missing month with no item is the one refusal, because popularity is a share of that month units and defaulting to this month would answer about a period the caller did not name. Recipe cost resolves the menu, then the recipes, then supplier prices, and reports which answered.',
