		'fnb_duplicate_invoice_scan' => array(
			'class' => 'Nvoos\\Core\\Tool\\Fnb\\FnbDuplicateInvoiceScanTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the duplicate invoice scan (Proposal 164 section 164.73). Three facts are pinned: the duplicate key rounds the amount to whole units, so 1,250.40 and 1,250.00 collide; the stock-purchase line is never reported as missing a budget line because the budget deliberately omits it; and no_budget_line is capped at 50 while the duplicate list is not, because a duplicate is the finding. The description promises large price jumps but the WordPress code does not attempt them, so neither does the port - M-19 is the metric for that. Flags only, as the note says.',
