			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the CSV/PDF exporter (Proposal 164 section 164.75), including the client aliases client-r01/client-r02/client-r03 to R-14/R-05/R-08. CSV flattens sections into section/key/value rows and stores them through the file registry rather than a csv_data_dir path; PDF renders through HtmlToPdfInterface rather than the DomPDF-or-gated-tool ladder, and an unbound renderer is the same named refusal with the same advice (export CSV). Both formats refuse by name when no file registry is bound, because a temporary path would be a file that disappears. Requires edit_posts and declares the write; the WordPress row claims read-only while writing a file.',
