			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the Report library (Proposal 164 section 164.75): R-01 to R-14 assembled from the metric engine by FnbReportBuilder, plus the Draft header fnb_save_draft consumes. An unknown id is the only refusal; an unreadable table degrades the section that needs it, as in WordPress (four reports print an unavailable line). money() follows the tenant profile currency decimals rather than the whole-units rule its WordPress docblock claims. R-01 counts undated rows because search_table never skips an unparseable date - the same quirk fnb_search_table pins. Popularity share is within the item type, so a one-food menu sees 100%.',
