			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the Draft listing (Proposal 164 section 164.75) over the same fnb-drafts collection, newest first. Keeps the WordPress keys name (id plus .md), path (the record locator) and bytes (length of the stored markdown), and adds title, updated_at and total so the 200-record page cap is visible rather than silent.',
