			'reason' => 'Ports M-19 with the month echoed back (Proposal 164 section 164.74). A month is required because an impact has no meaning without a period; the engine does the work and the wrapper adds only the refusal. This metric is what the duplicate-invoice description promises as large price jumps but that tool never runs.',
