			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the F&B table read over TabularReaderInterface (Proposal 164 section 164.71): the 18-table catalogue (generated from the Pro data source), the three-pass column resolver, and the header index the metric engine reads. A host maps a table to a file under the toolkit settings table_map; the WordPress Drive connection cascade, the CPT-backed tables and the native-storage hint are absent because this runtime has one table source and no F&B post type. connection_id is gone rather than accepted and ignored. limit keeps the WordPress floor of 200 and truncated is computed against the unsliced count. source always reads fnb_data_source so a shape-compatible consumer can branch on it.',
