			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the Draft writer (Proposal 164 section 164.75): title sanitising, markup stripping, Draft status and the never-send-or-order contract. The draft is a Paper Store record in fnb-drafts - id from the title slug, body { markdown } - rather than a markdown file or a Google Doc, because this runtime has neither a drafts directory nor a Drive connection. Re-saving the same title replaces the record, as the file write did. Deviation recorded: WordPress inherits the base read capability and read-only flag on a tool that writes; here it requires edit_posts and declares state-changing and write, so the read-only profile gate cannot claim nothing changed.',
			'evidence' => 'lib/core/tests/Unit/Tool/FnbReportToolsTest.php',
