			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the F&B table filter over TabularReaderInterface (Proposal 164 section 164.71). Two WordPress behaviours are pinned rather than corrected: a column with no value means "is present" (the cell is non-empty), and a row whose date does not parse passes a date range because only a parsed date is compared. column and date_column pass through sanitize_key, so a caller supplies canonical names. The scan is a full pass capped at limit (default 500) because there is no index to push the filter into. The payload keeps the WordPress key set, except that source reports the table source rather than a hardcoded string.',
