		),
		'generate_cloudflareai_image' => array(
			'class' => 'Nvoos\\Core\\Tool\\GenerateCloudflareAIImageTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'evidence' => 'docker/laravel/app-skeleton/tests/Feature/ImageAndFileToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'openWorldHint' => true ),
		),
		'generate_compliance_report' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\GenerateComplianceReportTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress compliance dashboard over ContentStoreInterface (Proposal 164 section 164.156). Two promise defects. The schema accepted json, pdf and excel, and the handler read the value, echoed it back as format and returned the same JSON every time, so a caller who asked for a pdf received JSON labelled pdf; this runtime has no PDF writer, so the port serves json and refuses the other two naming generate_pdf and generate_excel, which are served and take a structured payload. And a custom date range with a missing date was ignored rather than refused, returning the whole estate while the response said custom; the port requires both dates, validates them and checks the order. Three arithmetic guards: an unreadable expiry is counted in unreadable_expiry instead of becoming a very negative day count, an approval interval that precedes its submission is excluded from the average and counted, and approval_rate is defined as the share of registrations whose status is approved or active rather than left to be over-read. Status matching normalises the term name, so Under-Review and under_review agree.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryReportsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'generate_cost_analysis' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\GenerateCostAnalysisTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress cost analysis over ContentStoreInterface (Proposal 164 section 164.156). A non-numeric fee was cast to zero by (float), so a registration with an unreadable amount contributed nothing and the total looked complete; the port counts those values in unparsed_fees and names the fields, because the arithmetic cannot do otherwise but the response can say so. The same custom-range defect as its companion report is fixed the same way. The twelve-month renewal projection is month-aligned, where strtotime of plus twelve months overflows from the 29th to the 31st, and its month keys come from the parsed expiry date rather than a substring. average_cost_per_registration divides by the registrations actually summed rather than the query total, so a capped read cannot understate it, and truncated reports the cap. Amounts carry no currency because the records carry none; currency is reported as null rather than invented.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryReportsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'generate_country_performance' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\GenerateCountryPerformanceTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress per-country performance report over ContentStoreInterface (Proposal 164 section 164.157). The comparison block was mostly null: highest_approval_rate and fastest_processing both called array_keys with a value search against rows that are arrays, so the search always came back empty and the [0] on it produced null with a warning, and highest_volume was simply the first row after sorting, so it named whichever country led the caller sort rather than the largest estate. All three are computed by key comparison, and an average nobody measured is null instead of a division by zero — count of array_filter over all-zero averages is zero. authority was read from the first registration of a country and reused for all of them, so a country with two authorities reported one and an empty first value made the whole country empty; the port keeps the first non-empty value and adds the distinct authorities list. An unreadable expiry counts as expired, the safe direction, and is counted; a negative approval interval is excluded and counted; sort_by is validated rather than used as an array key. The compliance score keeps the 60 approval 40 expiry weights.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryAnalyticsReportsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'generate_eca_analytics' => array(
			'class' => 'Nvoos\\Core\\Tool\\Classroom\\GenerateEcaAnalyticsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Participation, capacity, financial and engagement analytics over the activity and attendance rows this runtime stores (Proposal 164 section 164.58), with Chart.js-shaped series. The financial summary is cost x enrolments from the roster and is labelled a projection: there is no payments ledger here.',
			'evidence' => 'lib/core/tests/Unit/Tool/EcaReadToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'generate_eca_participation_report' => array(
			'class' => 'Nvoos\\Core\\Tool\\Classroom\\GenerateEcaParticipationReportTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'A participation report for one activity, one student, a year group or the whole school (Proposal 164 section 164.58), as JSON with columns or as a rendered markdown table. `term` is free text because that is what `_eca_term` stores; the WordPress enum would refuse real terms the data holds.',
			'evidence' => 'lib/core/tests/Unit/Tool/EcaReadToolsTest.php',
