		'generate_excel' => array(
			'class' => 'Nvoos\\Core\\Tool\\GenerateExcelTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'MediaWorkerOfficeWriter implements OfficeWriterInterface over the media worker `POST /api/document/excel` (exceljs); needs `oos.media_worker.url` at runtime. Deterministic formatter, so no model is involved despite the WordPress flagship declaring `requires-model`.',
			'evidence' => 'docker/laravel/app-skeleton/tests/Feature/PdfDocumentAdapterTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => false ),
		),
		'generate_expiry_forecast' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\GenerateExpiryForecastTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress expiry forecast over ContentStoreInterface (Proposal 164 section 164.154). The monthly timeline was built with strtotime of plus N months from today, and PHP month arithmetic overflows on the 29th to 31st, so on 31 January the plus one month key was March and the February bucket never existed; because the counter only incremented when the bucket existed, every February expiry was dropped from the timeline on three days out of thirty one. The port builds buckets from the first of the month, where the arithmetic cannot overflow, and makes the horizon the last day of the final month so a bucket exists exactly when its month is inside the forecast. The timeline also counted only low-risk rows, where WordPress counted every non-expired row inside the horizon; that is restored. The four day-based bands are unchanged, and records inside no band and no bucket are counted in beyond_horizon instead of vanishing from the summary. An unreadable date is expired with a null day count and named, and both numeric bounds are validated rather than clamped.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryExpiryForecastTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'generate_password' => array(
			'class' => 'Nvoos\\Core\\Tool\\Orchestration\\GeneratePasswordTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the vault password generator (Proposal 164 section 164.77) with random_int over the combined charset. Pinned: there is no per-set guarantee, so a password can lack a digit with numbers enabled; avoid_ambiguous filters letters and digits only; and the 0-4 strength scale cannot reach 4 because the maximum raw score is 7 and it is halved to 3. Length 12-128 and count 1-10 are refused by the tool, so the vault service silent reset to 20 is not reachable. Flags are read-only and local-only, not idempotent, because the same arguments deliberately produce a different secret.',
			'evidence' => 'lib/core/tests/Unit/Tool/OrchestrationUtilitiesTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => false ),
		),
		'generate_pdf' => array(
			'class' => 'Nvoos\\Core\\Tool\\GeneratePdfTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Composes HTML through HtmlFormatter and renders it with the bound HtmlToPdfInterface (the media worker `POST /api/pdf/generate`), then stores through FileVisibilityStoreInterface. Deterministic formatter, so no model is involved despite the WordPress flagship declaring `requires-model`; the WordPress tool also could not have worked, because it delegated `content` to an operation that required `description` (Proposal 164 section 164.31).',
			'evidence' => 'lib/core/tests/Unit/Tool/GeneratePdfToolTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => false ),
		),
		'generate_pipeline_report' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\GeneratePipelineReportTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress pipeline report over ContentStoreInterface (Proposal 164 section 164.157). The bottleneck list sorted average_stage_times in place with arsort and then returned the same array, so a field named average_stage_times came back ordered by value with no explanation; the port sorts a copy and returns the averages keyed by stage, with bottlenecks as a list carrying the sample count behind each average because a slow stage measured once is not a bottleneck. The six trend buckets used strtotime of minus N months from today, which overflows from the 29th to the 31st and produced a duplicate or missing month key, so a six-month trend could show five buckets; keys are built from the first of the month. total_registrations was the query found_posts while the pipeline was built from the first 1000 rows, so the two fields disagreed for a larger estate; the port reports the grouped count and sets truncated. Stage time is time since submission, not time in the stage, and the field keeps that meaning with the definition stated; negative intervals and unreadable dates are excluded and counted.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryAnalyticsReportsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'generate_submission_pack' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\GenerateSubmissionPackTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress submission pack over ContentStoreInterface (Proposal 164 section 164.158). Fourth instance of the family default fault and the one that removes the artefact: include_cover_letter and include_index are declared true and read with empty, so a bare call stored a pack with cover_letter and document_index null — the two things the tool assembles. The port applies the declared defaults. WordPress also kept a second copy of the required-document table here, which could disagree with validate_document_checklist, so the table now lives once in RegulatoryTool and both tools read it; the comparison folds case for the reason section 164.152 recorded, since a document uploaded as LoA otherwise read as missing and refused the pack. A missing type refuses through the canonical envelope with the missing list rather than a bespoke error code, because a pack that omits a required certificate is worse than no pack. The manifest is written with update() and its meta merged; the letter and the index are strings, and no file is claimed.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatorySubmissionPackTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => false ),
		),
