			'reason' => 'Ports both modes (Proposal 164 section 164.81): research (query plan by report type and depth, web search, ProviderRouter synthesis at the WordPress 4,000-token budget, JSON extraction, TOC and references assembly) and formatting (pre-written sections). Adaptations: the search collaborator is WebSearchTool, whose parameter is count and whose item shape uses description rather than snippet; no search tool means empty sources, as WordPress behaved; no router returns completion_unavailable. Corrections: a failed Paper Store save or draft creation is named in paper_store_error / draft_post_error instead of dropped, and the saved record type is research-report rather than a duplicate of the collection name. str_word_count is kept so the counts match.',
