		'get_apple_messages' => array(
			'class' => 'Nvoos\Core\Tool\ChatChannels\GetAppleMessagesTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the Apple Messages for Business history reader (Proposal 164 section 164.108). Apple publishes the REST API its Messaging Service Providers implement rather than an API a business calls, so the endpoint, the token and the response schema belong to the caller provider; the tool constrains only what it can know. Corrections: the MSP URL must be a public https endpoint, where WordPress accepted a loopback host and a URL carrying userinfo with the bearer token attached; cursors are bounded instead of forwarding unbounded sanitize_text_field output; status defaults to the open value the schema declares, where WordPress omitted the parameter and let the provider choose; and the query is RFC 3986 encoded. The reply carries the decoded document under response and any conventional collection as items, because the response schema is the gateway s and a projection would drop fields the caller needs. Gated on manage_options.',
			'evidence' => 'lib/core/tests/Unit/Tool/ChatChannelGatewayToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
		),
		'get_appointment_details' => array(
			'class' => 'Nvoos\\Core\\Tool\\Calendar\\GetAppointmentDetailsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the appointment reader (Proposal 164 section 164.82) over the same meta family the writers store, so a booking created by any sibling tool reads back without a second path. include_history adds the activity log, the change history and the reschedule/cancellation markers; include_metadata adds the _custom_ fields. The content store read rule is enforced where WordPress checked only manage_options. start_time/end_time keep the stored UTC form and start_time_iso/end_time_iso are added for a machine-readable time.',
			'evidence' => 'lib/core/tests/Unit/Tool/CalendarAppointmentToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'get_available_slots' => array(
			'class' => 'Nvoos\Core\Tool\Calendar\GetAvailableSlotsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the slot grid for one date (Proposal 164 section 164.83) from the weekday business-hours rule, advancing by slot_duration + buffer_time and dropping any slot that overlaps a booked appointment or a blocked range. Corrections: blocked ranges and buffer_time were both ignored before, although the tool guidance promised the first and the rules stored the second; the weekday is now read as UTC, where gmdate on a strtotime date shifted the day west of Greenwich; and duration_minutes is clamped to 15-480 minutes, where absint allowed a zero-length or unbounded slot. An empty result carries day_of_week and the effective business_hours rule, so a disabled day, a missing rule and a fully booked day are distinguishable. Past slots are listed, because backfilling is allowed: available means not taken, not future.',
			'evidence' => 'lib/core/tests/Unit/Tool/CalendarAvailabilityToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
