		'get_calendar_view' => array(
			'class' => 'Nvoos\Core\Tool\Calendar\GetCalendarViewTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the unified calendar view (Proposal 164 section 164.84) over the three published types the project toolkit writes. Corrections: a project or event that spans the whole window is visible now, because the query uses start <= window_end AND end >= window_start rather than asking whether either bound fell inside the range; the range is validated and ordered; include_types is validated instead of silently ignoring a typo; assignee and attendee filters use the portable quoted-ID LIKE that list_projects relies on. Items are date-sorted with projects, tasks and events keeping their order on a shared date. The external booking systems are not merged: this runtime binds no booking adapter, and the WordPress argument that enabled them was absent from its own schema.',
