			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress contact timeline over ContentStoreInterface (Proposal 164 section 164.64): the same five arguments, the all default, the 50/500 clamp, newest first, and a read capability. Deviation: the WordPress original reads only the legacy _activity_* keys, which no toolkit code writes (create_crm_activity stamps activity_type, related_type and related_id). The port reads both families so a migrated row and a toolkit-written row are reachable, matching on _activity_contact_id or on a contact-bearing related_id (lead or contact). The inclusive date range is applied while walking 200-row pages, because ContentQuery has no date clause and filtering one page would drop rows.',
			'evidence' => 'lib/core/tests/Unit/Tool/CrmInteractionToolsTest.php',
