			'reason' => 'Ports the iCloud Drive file-metadata reader (Proposal 164 section 164.108). Apple has no public third-party drive API, so the tool reads through a gateway the host runs. Corrections: the gateway URL must be a public https endpoint, where WordPress accepted a loopback host and a URL carrying userinfo with the bearer token attached; and the file id is required and bounded rather than forwarded unbounded. The projected name, size, content type and modification time default to null rather than an empty string, so a caller can tell absent from empty, and the decoded document is kept under response because the schema is the gateway s. Gated on manage_options.',
