			'reason' => 'Ports the OneDrive item reader (Proposal 164 section 164.104). One drive item read by id or by path, returning metadata rather than bytes. Corrections: exactly one of item_id and file_path is accepted, where WordPress preferred the id and silently ignored the path; and the path rejects empty, dot and dot-dot segments, which percent-encoding does not change, where WordPress encoded the segments but allowed them. Rows project id, name, size, folder flag, child count, MIME type, web URL and last-modified time. Gated on manage_options.',
