		'get_teams_channels' => array(
			'class' => 'Nvoos\Core\Tool\ChatChannels\GetTeamsChannelsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the Teams channel list (Proposal 164 section 164.104). One /teams/{team_id}/channels read; the team id is validated as a GUID and the path is composed from encoded segments, where WordPress interpolated sanitize_text_field output that leaves slashes and dots intact. Corrections: the reply carries next_link when Graph sends @odata.nextLink, which WordPress dropped, so only the first page of a large team was ever visible; rows are projected to id, display name, description, membership type and web URL. next_link is only accepted back when it is https on graph.microsoft.com or graph.microsoft.us, because it is fetched with the caller bearer token. Gated on manage_options.',
			'evidence' => 'lib/core/tests/Unit/Tool/ChatChannelGraphToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
