			'probe' => 'call',
			'reason' => 'Ports the Teams message reader (Proposal 164 section 164.104). One /teams/{team_id}/channels/{channel_id}/messages read with $top clamped to 1-50. Corrections: the channel id is validated to the characters a Teams channel id uses and percent-encoded, where WordPress passed sanitize_text_field output into the path; the reply carries next_link where WordPress dropped @odata.nextLink; rows are projected to id, reply target, type, subject, body text and content type, sender display name, timestamps and web URL; and a non-numeric top falls back to 50 rather than absint to one. Gated on manage_options.',
			'evidence' => 'lib/core/tests/Unit/Tool/ChatChannelGraphToolsTest.php',
