			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the updates reader (Proposal 164 section 164.102). One getUpdates, clamped to 1-100, with the offset as the acknowledgement cursor. Corrections: each update is flattened to update id, type, message id, chat id, date, text and sender, where WordPress returned Telegram document whose shape depends on the update type and nests the message under callback_query.message; next_offset (last id plus one) is returned, where the caller had to know the rule; and a non-numeric limit falls back to 100 instead of absint to zero and then one. Gated on manage_options.',
