		'get_unconfirmed_bookings' => array(
			'class' => 'Nvoos\Core\Tool\Calendar\GetUnconfirmedBookingsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the pending-booking reader (Proposal 164 section 164.85) with the same key repair: _status = pending and no _confirmation_sent_at, over _start_time and _appointment_type, instead of the WordPress _appointment_status IN (unconfirmed, pending, empty), which no writer could produce. create_appointment now stamps _confirmation_sent_at when the transport accepts the notification, so a booking confirmed at creation is not listed again; a pending record with a stamp is excluded. Oldest first, boundary days included, truncated reported. Read-only.',
			'evidence' => 'lib/core/tests/Unit/Tool/CalendarTriageToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'get_order_analytics' => array(
			'class' => 'Nvoos\\Core\\Tool\\Ecommerce\\GetOrderAnalyticsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the order analytics summary (Proposal 164 section 164.178) over OrderStoreInterface, with the aggregate computed by the store as a GROUP BY rather than by hydrating the window. The reference fetched every order in the range with limit -1 and hydrated each one four times, once for the summary and again for trends, top products and customers, so the cost grew with the store rather than with the window. Two totals are reported and only one is called revenue: gross_total sums every order in the window, revenue sums only processing and completed, the two statuses WooCommerce counts as revenue because payment has been received, and the reference added every total regardless of status and called the result total_revenue, so cancellations, failures and refunds were counted as takings. refunded is excluded rather than subtracted because the model stores the order total and not how much came back. The currency is required and is a filter: the store aggregates one currency and reports the rest as excluded_orders, where the reference summed raw floats across currencies and labelled the sum with the store currency. group_by is a closed enum, so an unknown value is a field error rather than a silent fall-through to day. Periods are bucketed from calendar days and weeks use the ISO week-year, so the week spanning New Year is one bucket rather than two, and a bucket counts only revenue-bearing orders so the figure under revenue is revenue. include_trends is opt-in. include_products, include_customers and top_count are all supported now: sections 164.180 and 164.181 added the line and customer aggregates they need. The customers section counts registered accounts rather than the reference email-or-id key, and its new-versus-returning split is not reproduced because it counted orders in the window rather than customer history. payment_methods is not reported because the order model has no payment-method field. Dates are parsed strictly and date_to includes the day it names. Read-only.',
			'evidence' => 'lib/core/tests/Unit/Tool/GetOrderAnalyticsToolTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'get_uninvoiced_orders' => array(
			'class' => 'Nvoos\\Core\\Tool\\Ecommerce\\GetUninvoicedOrdersTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the uninvoiced-order listing (Proposal 164 section 164.174), the first tool over the new OrderStoreInterface, bound to OrderStore on the nvoos_orders and nvoos_order_lines tables, so the constructor is satisfiable and the tool is ready rather than unavailable. Four reference defects are corrected rather than reproduced: the minimum amount was applied after the limit, so asking for ten orders of at least 100 could return none while a hundred qualifying orders sat behind the page; floatval turned an unusable amount into 0.0 and silently switched the filter off; dates were sanitize_text_field output concatenated into an after...before string and an unparseable date was ignored; and absint turned a negative customer id into a positive one. The minimum amount now requires a currency, because an untyped float compared across a mixed-currency store is not a comparison; the adapter compares total_currency and total_minor, so orders in another currency are excluded rather than ranked against the bound. date_to includes the day it names, both bounds must round-trip as YYYY-MM-DD, and the response reports the match count and the page size separately, where WordPress called the page size the total. A page holds at most 100 and reports total_pages so a billing pass can iterate, instead of the reference 1000-row response. edit_url is present and always null because this runtime has no order admin screen.',
			'evidence' => 'lib/core/tests/Unit/Tool/GetUninvoicedOrdersTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
