			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'MediaWorkerVideo over the media-worker `POST /api/video/info` route, which runs ffprobe. Read-only. `extract_video_metadata` is the WordPress second slug for the same report and is deliberately not ported.',
