		'get_videos_without_thumbnails' => array(
			'class' => 'Nvoos\\Core\\Tool\\GetVideosWithoutThumbnailsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Reads the file registry: videos by `mime_type` prefix through `FileStoreInterface::findByMetadata()`, then `FileDerivativeStoreInterface::sourceIdsWithDerivative()` to say which of them already have a poster (`derived_role` = poster). Two scans, not one per video, and the two share a bound so a poster cannot be missed because one scan stopped a row earlier. Refuses by name when the host has no registry (`no_file_registry`) or a registry that cannot record relationships (`no_derivative_registry`). Bounded: the registry scans its newest rows, so the report is a window and `truncated` says so (Proposal 164 section 164.46).',
