		),
		'get_videos_without_transcripts' => array(
			'class' => 'Nvoos\\Core\\Tool\\GetVideosWithoutTranscriptsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'The same two scans as `get_videos_without_thumbnails`, asking for the caption role instead of the poster role. A transcript here is the stored `.srt`/`.vtt` sidecar that `generate_video_captions` writes; `transcribe_video` returns text and stores nothing, so an unsaved transcript is correctly listed again — which the description says, because a caller who just transcribed will otherwise read the repeat as a bug. WCAG 2.2 SC 1.2.2 is why the gap is worth measuring (Proposal 164 section 164.46).',
			'evidence' => 'lib/core/tests/Unit/Tool/VideoAssetInventoryToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'get_workflow_execution_log' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\GetWorkflowExecutionLogTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Fixes two filter guards that kept what they should have dropped: WordPress guarded with isset, so an entry without rule_id passed the test and filtering by rule returned that rule entries plus every entry missing the field. Dates are compared on the first ten characters rather than through strtotime, unreadable timestamps are counted and excluded by a date filter instead of sorting as if they were from 1970, and by_action_type is counted over the matched set with total, matched and store_entries reported separately. The 200-entry option cap is not ported because it was an option-size decision; store_entries makes growth visible. The log is an edit log: execute_rule is in the enum but nothing produces it (Proposal 164 section 164.159).',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryWorkflowRulesTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
