			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the function plotter (Proposal 164 section 164.169) through GraphRendererInterface over POST /api/math/graph, which samples with mathjs and renders with chartjs-node-canvas in one call so a plot is one round trip rather than one per sample. In WordPress the tool was a filter with no implementation anywhere in the plugin, so every install could only reach the engine-missing branch while the tool still required upload_files: it advertised a capability it could never perform. Six input defects are fixed: the expression went through sanitize_text_field, an HTML filter applied to a grammar; the required function argument was read without isset and warned before the error branch; width and height were absint-ed with no bound though the schema declares 400-2000 and 300-1500; show_grid was read with a bool cast, for which the string false is true; sanitize_hex_color returns null for an invalid colour and the null was passed through to the renderer; and x_range was indexed without a shape check. A window that yields fewer than two finite values is a validation failure rather than an empty plot, a pole is a gap in the line instead of a failed request, and an undefined symbol is reported with the evaluator message. Delegated rather than ready because the contract is bound by the provider and this runtime cannot honour it without oos.media_worker.url and the native canvas binding.',
			'evidence' => 'lib/core/tests/Unit/Tool/GraphFunctionToolTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => false ),
		),
		'gtmetrix_account_status' => array(
			'class' => 'Nvoos\\Core\\Tool\\GTmetrix\\GtmetrixAccountStatusTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the account reader (Proposal 164 section 164.91) as the first slug over a client written against HttpClientInterface and getApiKey( gtmetrix ). One credit-free GET /status. An absent balance stays null rather than becoming zero, because a caller reading 0 would think the account empty; the WordPress tool passed the raw attribute through and could not tell an absent key from a real value. Reads are declared external-api, network-dependent, read-only and requires-credentials; the WordPress cacheable flag is not carried because a live balance is not cacheable.',
			'evidence' => 'lib/core/tests/Unit/Tool/GtmetrixReadToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
		),
		'gtmetrix_analyze_report' => array(
			'class' => 'Nvoos\\Core\\Tool\\GTmetrix\\GtmetrixAnalyzeReportTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the deterministic analysis (Proposal 164 section 164.94) over the score engine and the fix matcher: Core Web Vitals against the 2026 thresholds, the page-weight budget, the LCP phases, the impact-ordered top ten audits and the mapped fixes with unfixable and unknown buckets. Corrections: a report without a score is no longer graded F (the grade is derived only when a score exists); a failed Lighthouse fetch is reported in a lighthouse block with its classified code instead of reading as an empty fix list; the budget reports the next class and the headroom rather than the current class with zero; every fix that names an audit is returned, so the duplicate-tag advice is reachable. url is refused by name because the core keeps no local snapshots. Gated on read.',
			'evidence' => 'lib/core/tests/Unit/Tool/GtmetrixAnalysisToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
		),
		'gtmetrix_compare_reports' => array(
			'class' => 'Nvoos\\Core\\Tool\\GTmetrix\\GtmetrixCompareReportsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the before/after comparison (Proposal 164 section 164.94) over the report-delta rules: two scores against a five-point absolute move, four timings and two sizes against a percentage move, and cumulative layout shift against an absolute 0.05, with regressed, improved or steady verdicts and a regressed count. A metric absent on either side is omitted rather than reported as steady, because not measured and did not move are different. url is refused by name because the core keeps no local snapshots; each side is named by its datum id with the requested id as fallback. Gated on read.',
			'evidence' => 'lib/core/tests/Unit/Tool/GtmetrixAnalysisToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
