			'probe' => 'call',
			'reason' => 'Ports the alert-event history (Proposal 164 section 164.97), most recent first: the condition that fired with the value that triggered it, or a report-generation failure with its error slug, plus the notified recipients. Corrections: the limit is sent as page[size] and bounded to 1-100, where WordPress fetched the default page and sliced it afterwards; and the alert and recipient rows are projected to scalars. Costs no credits. Gated on read.',
			'evidence' => 'lib/core/tests/Unit/Tool/GtmetrixMonitoringToolsTest.php',
