		'gtmetrix_get_lighthouse_audits' => array(
			'class' => 'Nvoos\\Core\\Tool\\GTmetrix\\GtmetrixGetLighthouseAuditsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the audit reader (Proposal 164 section 164.93) over the lighthouse.json resource. Audits are ordered by the GTmetrix _impactScore with the published band table (Low at or below 0.12, Med-Low 0.24, Med 0.36, Med-High 0.48, High above), because impact is what says a fix is worth making. An unknown min_impact, including None, is refused instead of silently meaning no filter, and the limit is bounded to 1-200 where WordPress checked the bound after appending, so a limit of 0 still returned one audit. The LCP phase breakdown is read when present and marked estimated otherwise. Costs no credits.',
			'evidence' => 'lib/core/tests/Unit/Tool/GtmetrixReportToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
