		'gtmetrix_get_report' => array(
			'class' => 'Nvoos\\Core\\Tool\\GTmetrix\\GtmetrixGetReportTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the report reader (Proposal 164 section 164.93). One credit-free GET /reports/{id} flattened into grade, five scores, nine timings, page bytes and requests, and the resource names. The correction: JSON:API puts the report links beside attributes, and WordPress read attributes.links, so the resources list was always empty on a real response; the sibling block is read here. Absent numbers stay null instead of a PHP notice, a cumulative layout shift keeps its decimals, and the snapshot preference is dropped because the poller that wrote those snapshots does not exist in the core, so the report is read live. Gated on read.',
			'evidence' => 'lib/core/tests/Unit/Tool/GtmetrixReportToolsTest.php',
