		'gtmetrix_get_resource_summary' => array(
			'class' => 'Nvoos\\Core\\Tool\\GTmetrix\\GtmetrixGetResourceSummaryTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the resource-summary reader (Proposal 164 section 164.93) over the resource-summary resource: seven categories with counts and transferred and uncompressed bytes, heaviest first for page-weight triage. The body is unwrapped from either shape (bare object or JSON:API attributes), non-array categories are skipped, and a non-scalar label falls back to the category name instead of reaching the reply as an array. Byte counts are non-negative integers. Costs no credits.',
			'evidence' => 'lib/core/tests/Unit/Tool/GtmetrixReportToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
