		'gtmetrix_list_report_resources' => array(
			'class' => 'Nvoos\\Core\\Tool\\GTmetrix\\GtmetrixListReportResourcesTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the resource inventory (Proposal 164 section 164.93) from the report links. The correction: WordPress keyed its annotation table by endpoint file names (net.har, lighthouse.json, resource-summary) but the API returns link names (har, lighthouse, resource_summary), so every lookup missed and har - a raw network capture the client refuses to fetch - was listed as downloadable. The table is keyed by link name, carries the endpoint a caller would fetch, adds report_pdf_full, report_url and filmstrip-frame, and marks optimized_images and pagespeed_files as 24-hour resources. Lists only and never fetches; the HAR and analysis-options links are marked sensitive. Costs no credits.',
			'evidence' => 'lib/core/tests/Unit/Tool/GtmetrixReportToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
