			'reason' => 'Ports the device reader (Proposal 164 section 164.91). One credit-free GET /simulated-devices with a phone or tablet filter. WordPress sanitised the category and silently returned an empty list for an unknown value, which reads as a plan limitation; the port refuses it instead. Costs no credits.',
