		'gtmetrix_retest_page' => array(
			'class' => 'Nvoos\\Core\\Tool\\GTmetrix\\GtmetrixRetestPageTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the page retest (Proposal 164 section 164.96): POST /pages/{id}/retest reuses the saved analysis options and spends one credit. Corrections: the daily budget is reserved before the call and released when the API refuses or the reply carries no test id, the same reservation start_test uses; and a url resolves through filter[url] with an exact, case-insensitive match, where WordPress read a local snapshot map the core does not have. No match is gtmetrix_page_not_found with the candidates, several matches is gtmetrix_page_ambiguous rather than a guess. The host allowlist still applies to a supplied URL. Gated on manage_options, which is what WordPress enforced.',
			'evidence' => 'lib/core/tests/Unit/Tool/GtmetrixPagesToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'gtmetrix_set_alert_conditions' => array(
			'class' => 'Nvoos\\Core\\Tool\\GTmetrix\\GtmetrixSetAlertConditionsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the full-replace alert writer (Proposal 164 section 164.97). Corrections: a malformed condition refuses the whole call by index instead of being skipped while still counting toward the ten, which could silently drop an alert the caller believed it had set; a threshold must be numeric, where a (float) cast turned a word into zero and passed the non-negative check; the count is the stored set the API returned rather than the list that was sent; and send_to is offered and validated, where WordPress never sent it so a Team organization could not set recipients at all. An empty list clears the alerts. All-or-nothing matches replace semantics. Gated on manage_options.',
			'evidence' => 'lib/core/tests/Unit/Tool/GtmetrixMonitoringToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
		),
		'gtmetrix_set_monitoring' => array(
			'class' => 'Nvoos\\Core\\Tool\\GTmetrix\\GtmetrixSetMonitoringTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the monitoring switch (Proposal 164 section 164.97) over POST /pages/{id}/performance_monitor. The frequency is case-folded and validated against the documented set, and the reply reports the requested frequency and the state the API stored separately, because none is stored as no and a plan can refuse hourly. A plan ceiling is classified as gtmetrix_plan_denied (E40303) rather than an invalid request, so a caller does not retry a permanent refusal. Gated on manage_options.',
			'evidence' => 'lib/core/tests/Unit/Tool/GtmetrixMonitoringToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
		),
		'gtmetrix_start_test' => array(
			'class' => 'Nvoos\\Core\\Tool\\GTmetrix\\GtmetrixStartTestTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the credit-spending test starter (Proposal 164 section 164.92). Four corrections: credits are read from the response meta, which the WordPress client discarded so credits_left was always null and credits_used was a local estimate; the site daily budget is reserved in hundredths before the POST and released when the call is refused or returns no test id, where WordPress checked, started and only then recorded the charge so two concurrent calls both passed; an unknown report, retention, location, browser, device or throttle is refused by name instead of being silently dropped by sanitize_key, which ran tests with options the caller did not ask for; and no WP-Cron poll is scheduled, the tool returns test_id and the next step. The host allowlist still defaults to the site host plus configured extras and fails closed when no host is known. The cost table (report, retention, video) is shared with the later sweeps so no two tools disagree about a price. Gated on manage_options.',
			'evidence' => 'lib/core/tests/Unit/Tool/GtmetrixTestLifecycleToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
