			'reason' => 'Ports the five WordPress term actions over SettingsStoreInterface and ContentStoreInterface (Proposal 164 section 164.59). Terms live in the eca_terms setting; an activity belongs to a term when its stored term name matches, because this runtime writes no term id meta, and the description says so. Creation refuses a duplicate name for the same reason. Transition completes every active term, activates the target, optionally retags the outgoing activities, and scopes the default attendance reset to those activities while reporting its scope and count - the log holds dated totals only, so that deletion is irreversible. The WordPress historical snapshot key is not written because nothing reads it.',
			'evidence' => 'lib/core/tests/Unit/Tool/EcaWriterToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => true, 'idempotentHint' => false, 'openWorldHint' => false ),
