			'reason' => 'Ports the slash-command manager (Proposal 164 section 164.102): setMyCommands, deleteMyCommands and getMyCommands under a BotCommandScope. Corrections: a chat-level scope without its chat id, or chat_member without a user id, is refused, where WordPress sent an empty chat_id or user_id 0 to Telegram; a command name is lowercased and then validated, where WordPress stripped every character outside the allowed set so hello-world silently became helloworld; and an over-long description is refused, where WordPress truncated with byte-based substr that can split a multi-byte character. Gated on manage_options.',
