			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'MediaWorkerPdfMutator implements PdfMutatorInterface over the media worker `POST /api/pdf/merge` (pdf-lib); needs `oos.media_worker.url` at runtime. Page order is carried in the multipart field index, and the reply carries the merged page count so a caller can prove nothing was dropped.',
