		'merge_videos' => array(
			'class' => 'Nvoos\\Core\\Tool\\MergeVideosTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'MediaWorkerVideoComposition over `POST /api/video/compose` (operation `merge`) then `GET /api/video/download`, on one of two paths. `transition: none` copies: ffprobe every clip, refuse the first property that differs, then the concat demuxer with `-c copy` — because the demuxer does not fail on a mismatched frame rate, it silently writes a file with the wrong duration. `fade`/`dissolve` cannot copy (every frame in the overlap is a blend), so they re-encode: each clip is scaled/padded into the first clip frame and rate, the cuts are placed at `offset_i = (d₁ + … + d_i) − i × T`, and the audio is joined with `acrossfade` — mixed audio presence is refused because `acrossfade` needs a track on both sides. Measured on ffmpeg 8.1.2: 2 + 3 + 4 s with a 0.5 s fade is 8.000 s. `none` is the default; the WordPress tool declares `fade` and then does nothing, and a default that silently re-encodes would change every existing pipeline.',
			'evidence' => 'docker/laravel/app-skeleton/tests/Feature/VideoCompositionAdapterTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
