		'optimize_schedule' => array(
			'class' => 'Nvoos\\Core\\Tool\\Calendar\\OptimizeScheduleTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the schedule optimiser (Proposal 164 section 164.87), which on WordPress was a stub: utilization_rate 0.75 and average_gap_minutes 30 were literals, and the goal argument was accepted then ignored, so every call returned the same hardcoded 15 percent consolidation. The port measures the book instead. Counted appointments exclude cancelled and no-show rows and report them, booked minutes sum appointment durations, gaps are computed against the furthest end so an overlap cannot manufacture one, and capacity comes from the business_hours rules or is reported as unconfigured rather than guessed. Each goal produces different recommendations carrying the minutes and dates they were derived from. The scan ceiling and the one-year range cap are reported as truncated instead of silently sampling.',
			'evidence' => 'lib/core/tests/Unit/Tool/CalendarScheduleOptimisationTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'paper_store_export' => array(
			'class' => 'Nvoos\\Core\\Tool\\PaperStoreExportTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Reads one `query()` page through PaperStoreInterface. The JSON store scans the collection directory on every call, so assembling "everything" in a loop would re-read the same files once per page; the tool returns one page plus `total` and `next_offset`. The collection name is validated before the store sees it, because `query()` answers an unusable name with an empty page and an empty export reads as a finding. Order is pinned to `id` so a save cannot reorder a page mid-export; offset paging is still sensitive to concurrent creates and deletes, because the store has no snapshot. `cacheable` is deliberately absent although the WordPress tool declares it: the store can change between two identical calls.',
			'evidence' => 'lib/core/tests/Unit/Tool/PaperStoreToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'paper_store_import' => array(
			'class' => 'Nvoos\\Core\\Tool\\PaperStoreImportTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Upserts through PaperStoreInterface::save() with `overwrite` defaulting to true, as the WordPress tool does. Titles are checked here rather than left to the store: the reference schema promises `id` and `title` but only checks `id`, so a title failure surfaced as a store exception with store wording. A record with no id is reported as failed rather than counted as skipped, because "malformed" and "already exists" are different facts. `imported + skipped + failed` equals `total` by construction.',
			'evidence' => 'lib/core/tests/Unit/Tool/PaperStoreToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => true, 'idempotentHint' => false, 'openWorldHint' => false ),
