		'plan_schedules_from_workflow' => array(
			'class' => 'Nvoos\\Core\\Tool\\Orchestration\\PlanSchedulesFromWorkflowTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the workflow planner (Proposal 164 section 164.80): structured items or text with ## Category headings, keyword cadence and priority inference in the WordPress order, an 80-character name cap, and a 60-second offset per item so non-task ids do not collide. WordPress site state has no core counterpart and is documented: times are UTC, notify_email defaults to empty instead of admin_email, and an invalid address is dropped rather than failing the batch. dry_run persists nothing; without default_assistant_id each item becomes a wp_mcp_ai_workflow_reminder task carrying a JSON payload.',
