		'pro_batch_ocr' => array(
			'class' => 'Nvoos\\Core\\Tool\\ProBatchOcrTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'A loop over `PdfOcrInterface::recognize()` (media worker `POST /api/pdf/ocr`), resolving each `file_id` through `FileStoreInterface::getPath()`. No worker change was needed: the route already takes `dpi`, `max_pages`, `language` and a page budget, so the batch belongs in the tool (Proposal 164 section 164.39). `continue_on_error` defaults true so one unreadable file does not discard the batch; the WordPress-only `unlimited_ocr` and `deepseek_ocr` providers are refused by name rather than substituted with tesseract.',
			'evidence' => 'lib/core/tests/Unit/Tool/ProBatchOcrToolTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'pro_document_ocr' => array(
			'class' => 'Nvoos\\Core\\Tool\\ProDocumentOcrTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Reads the PDF text layer first through `PdfTextExtractorInterface` (`POST /api/pdf/extract`) and falls through to OCR only when the layer carries fewer than 32 characters per page. Two engines sit behind that fall-through: tesseract through `MediaWorkerPdfOcr` (`POST /api/pdf/ocr`), and any named vision provider through `VisionPdfOcr`, which renders each page with `PdfPageRendererInterface` (`POST /api/pdf/render` with `inline`) and transcribes it. `auto` is text layer, then tesseract, then vision: the free local engine first, because a caller who named no engine should not be billed per page. The two vision refusals are named separately (`no_page_renderer`, `no_vision_model`) because an operator fixes them differently. The self-hosted vLLM models stay refused by name, since this runtime has no address for them (Proposal 164 sections 164.40 and 164.44).',
			'evidence' => 'lib/core/tests/Unit/Tool/ProDocumentOcrToolTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
