			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress AI product actualization tool (Proposal 164 sections 164.130 and 164.131) as two model turns over ImageProductionInterface: generate the scene from scene_prompt, then compose the product into it, because this runtime owns no image blend and the compose route is its only two-image primitive. The integration prompt still tells the model the product must not be altered, and the placement hint reaches that prompt instead of being composite-only. Aspect ratios keep the WordPress set and round to a canvas both providers accept. The product is read through the file registry with the same ownership check ImageInput uses, so a caller cannot send a file it could not download. mode video composes the same still, submits it to the image-to-video route with wait false, and answers a queue job id; VideoGenerationPollHandler polls once per run, downloads the finished URL into the registry and completes with the media entry, so no request waits for the render. Two refusals carry a next step: composite mode needs a local blend this runtime does not ship, and background_mode remove needs a removal capability the worker does not expose, so auto is treated as preserve and the payload reports background_removed false rather than implying a cut-out. The image composition is stored through GeneratedMediaPersister and the worker scratch files are deleted.',
			'evidence' => 'lib/core/tests/Unit/Tool/ProductActualizationToolTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'printful' => array(
			'class' => 'Nvoos\\Core\\Tool\\Ecommerce\\PrintfulTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress Printful dispatcher (Proposal 164 section 164.118) as one tool with 25 grouped actions, keeping the single corpus slug so parity stays exact. Pinned to API v1 because Printful v2 is beta and states that sync products and product templates are not available in it, which would drop five actions; V2 also still returns the v1 error envelope for Catalog, Orders and Webhooks. Four corrections: no GET cache (the original keyed a transient on the URL alone, so two stores could share an entry), no per-user rate limiter (30/min per user against a provider limit of 120/min per account, so it was limit-shaped and did not limit), paging is a sibling of the payload rather than relabelling a single object as items, and the token plus optional store id are arguments instead of a Remote Sites connection store. The six-month statistics cap is enforced rather than merely documented. A 2026-11-27 probe of api.printful.com confirmed that the seven catalog reads answer without a token, so the schema says the token is this tool\'s requirement rather than the provider\'s.',
