			'reason' => 'Ports the WordPress country grouping over ContentStoreInterface (Proposal 164 section 164.147). One correction: WordPress computed each country statistics from the registrations list, which is empty when group_by_status filed the rows under by_status, so asking for both returned correct groups with an all-zero summary; the port summarises every row however it was grouped. include_stats now defaults to true as declared, the country filter is described as a name because that is what it compares, and a read gate was added.',
