		'renew_registration' => array(
			'class' => 'Nvoos\Core\Tool\Regulatory\\RenewRegistrationTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress renewal over ContentStoreInterface (Proposal 164 section 164.147). Creates a new registration carrying product, country and authority, typed renewal and pointed at the original, then stamps the original renewed_by and renewal_date so a superseded record is answerable. The COS number and dates are not carried, because a renewal is a new application; the old ones are recorded in the note body. The expected expiry is validated as ISO. WordPress had no capability check; the port requires edit_posts.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryRegistrationLifecycleTest.php',
