		'render_math_equation' => array(
			'class' => 'Nvoos\\Core\\Tool\\Math\\RenderMathEquationTool',
			'readiness' => 'delegated',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the LaTeX renderer (Proposal 164 section 164.167) against the media worker POST /api/data/render-math route, which already existed, so this port costs no worker release. The tool delegates through MathRendererInterface, bound to MediaWorkerMathRenderer, which sends the option names the route actually reads: WordPress sent the raw tool arguments, whose options are spelled display_mode and output_format, while the route reads displayMode and output, so every sidecar request fell through to its defaults and a caller asking for inline rendering got a centred block while a caller asking for MathML got HTML, with nothing said. The adapter also translates the schema spelling html_and_mathml into the KaTeX spelling htmlAndMathml, which the route would otherwise reject with a settings error that throwOnError does not catch. Corrections: the input was sanitised with wp_kses_post, an HTML filter that escapes angle brackets, so comparisons and angle-bracket LaTeX were corrupted before any parser saw them; the port passes the expression through untouched and lets KaTeX be the parser and sanitiser, with trust defaulting to false so href and includegraphics stay inert. check_katex_availability required a vendored katex.min.js and the node command on the host before the sidecar was tried at all, so a worker-routed site refused with engine_missing; the port asks the renderer instead. The tool was gated on enable_quiz_system although rendering does not depend on the quiz toolkit, so the association is now opt-in through quiz_id. throw_on_error is gone from the schema because the route hard-codes throwOnError false and an option that can only be false is not an option, and a non-empty macros map is refused by name rather than sent to a route that ignores it. The rendered string is returned as markup rather than html, because it held MathML whenever MathML was requested. render_time was a millisecond string on a render and the integer zero on a cache hit; render_time_ms is a float always, and the WordPress object cache is not reproduced because it was keyed on serialize() of the caller arguments, so quiz_id and save_rendered fragmented it. The quiz association wrote meta on whatever id it was given without checking that the item existed; the port requires the item and reports how many equations the quiz holds. Gated on edit_posts, matching the WordPress declaration and its handler.',
			'evidence' => 'lib/core/tests/Unit/Tool/MathRenderEquationTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => false ),
		),
