			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the chat-facing renderer (Proposal 164 section 164.80): six canonical modes over the stored envelope, every interpolated value escaped with htmlspecialchars(ENT_QUOTES), and an unrun schedule rendered as a notice. Divergence: WordPress passed authenticated html-safe output through wp_kses_post; the core has no kses, so raw mode escapes instead of returning unfiltered markup. Timestamps format in UTC. The declared capability is the narrower read_private_posts.',
