		'sales_performance_dashboard' => array(
			'class' => 'Nvoos\\Core\\Tool\\Ecommerce\\SalesPerformanceDashboardTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the sales dashboard (Proposal 164 section 164.179) over OrderStoreInterface. The reference is raw SQL over wp_posts and wp_postmeta: shop_order posts in wc-completed and wc-processing, _order_total for money and _customer_user for the customer. WooCommerce moved orders to its own wc_orders tables, where those rows do not exist, so on a modern store the reference returned a dashboard of zeroes and reported success; this tool reads the same order store as get_order_analytics, so the two cannot disagree. Revenue over the paid statuses processing and completed, orders, average order value, distinct buyers and the daily trend come from the store aggregate. include_refunds is refused when true because the flag added wc-refunded to the sum, and a refunded order carries its original total, so asking to include refunds increased revenue by the full value of every refunded order rather than netting anything; revenue already excludes cancelled, failed and refunded orders, and the model records no refunded amount to net with. average_order divided revenue by an order count computed only when orders had also been requested, so asking for revenue and average order value returned revenue alone; every requested metric is computed here. The currency is required and is a filter, where the reference summed a text column and labelled the result with the store currency. customers counts distinct buyers among revenue-bearing orders and ignores guest orders, which carry no customer id. The products metric is supported since section 164.180 added the line aggregate, and top_products_limit sizes it. conversion is refused because it needs sessions and traffic that no store here records. category_ids is refused because the product model has no category field and the reference filter could not have worked anyway, and an empty category list is accepted because it asks for nothing. The new_customers metric is supported since section 164.181 added the first-order-per-customer aggregate, and counts registered customers whose first paid order ever fell in the window. Dates are parsed strictly, date_to includes the day it names, a reversed range is a field error, and days counts both ends of the window where the reference rounded the timestamp difference. Read-only.',
			'evidence' => 'lib/core/tests/Unit/Tool/SalesPerformanceDashboardToolTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
