		),
		'send_eca_notification' => array(
			'class' => 'Nvoos\Core\Tool\Classroom\\SendEcaNotificationTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress notification sender over EmailServiceInterface (Proposal 164 section 164.59). Recipients are resolved from the live roster, an untyped roster row counts as confirmed, and every address is reported individually as sent or failed, so one bad address cannot hide the rest. A parent with no address is reported as no_parent_email. The attempt is appended to the notification log with a failed_count the WordPress log omits. The body reads the stored start and end times; the WordPress body reads a key its own create tool never writes.',
			'evidence' => 'lib/core/tests/Unit/Tool/EcaWriterToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'send_eca_parent_report' => array(
			'class' => 'Nvoos\Core\Tool\Classroom\\SendEcaParentReportTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress guardian report over EmailServiceInterface and ContentStoreInterface (Proposal 164 section 164.59). The address is the stored parent address when present and the student address otherwise, and the result names which role received it. The term filter is free text because terms are whatever manage_eca_term stores. This runtime has no achievements store, so include_achievements is honoured by stating that none are recorded and the result says achievements_included false. The send is appended to the student report log with the recipient role added.',
			'evidence' => 'lib/core/tests/Unit/Tool/EcaWriterToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'send_expiry_alerts' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\SendExpiryAlertsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress expiry alert over ContentStoreInterface and EmailServiceInterface (Proposal 164 section 164.155), the only writing tool in the family. WordPress resolved recipients from the argument, then a notification-settings option that configure_email_notifications writes, then admin_email; this runtime has neither an options store nor an administrator address, so the port takes the argument, falls back to recipients the host supplies at construction, and refuses the call when both are empty rather than sending to a guess. An invalid address was run through sanitize_email, which returns an empty string, and then handed to wp_mail, so the send failed silently and the response still listed the address; the port validates, drops and reports it in invalid_recipients. A host without a transport still receives the report with transport_available false, as the calendar notification tools already do. Already-expired registrations are excluded from the window and counted in expired_excluded. Two recorded gaps: the WordPress option log is not ported because there is no options store, and there is no idempotency guard, because this tool mails the operator team rather than a client and the caller controls cadence; test_mode is the preview. Gated on edit_posts, matching both the declaration and the handler, since the tool sends mail.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryExpiryAlertsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'send_group_email' => array(
			'class' => 'Nvoos\\Core\\Tool\\SendGroupEmailTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Sends through App\\Support\\Mail\\EmailService over Laravel Mail, bound in AppServiceProvider. AbstractTool::stringParam() strips tags, so is_html reaches the mailer but cannot carry markup - shared with WordPress (Proposal 149 section 138).',
			'evidence' => 'docker/laravel/app-skeleton/tests/Feature/SendGroupEmailToolTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'openWorldHint' => true ),
		),
		'send_group_email_validated' => array(
			'class' => 'Nvoos\\Core\\Tool\\SendGroupEmailValidatedTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Extends SendGroupEmailTool, so it shares the EmailService path and the same tag-stripping limitation (Proposal 149 section 138).',
			'evidence' => 'docker/laravel/app-skeleton/tests/Feature/SendGroupEmailToolTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'openWorldHint' => true ),
		),
		'send_apple_message' => array(
			'class' => 'Nvoos\Core\Tool\ChatChannels\SendAppleMessageTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the Apple Messages for Business text sender (Proposal 164 section 164.108). Apple publishes the REST API its Messaging Service Providers implement, so the endpoint and token are the caller provider s and the envelope is this family s convention, not Apple s native interactiveData shape; a gateway that speaks the native format must translate, and the description says so. Corrections: the MSP URL must be a public https endpoint, where WordPress accepted a loopback host and a URL carrying userinfo with the bearer token attached; an over-long body is refused, where WordPress sliced it at 2,000 characters so the message arrived cut mid-sentence; a message must name a conversation id or a recipient id, where WordPress accepted neither although both of its own property descriptions said one was needed; and the locale is validated as a BCP 47 tag. Gated on manage_options.',
			'evidence' => 'lib/core/tests/Unit/Tool/ChatChannelGatewayToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'send_apple_message_group' => array(
			'class' => 'Nvoos\Core\Tool\ChatChannels\SendAppleMessageGroupTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the Apple group sender (Proposal 164 section 164.108). Corrections: the 32-participant cap is enforced after sanitisation, where WordPress checked the raw array length so 40 entries of which 30 were blank passed and 32 valid entries plus one blank was refused; a malformed participant is refused, where WordPress skipped it so the group silently addressed fewer people than asked for; a group with neither an id nor participants is refused, where WordPress posted a group message that named no group; and multipleSelection is read as a boolean where the WordPress cast turned the string false into true. Shares the public-https endpoint guard all seven gateway tools use. Gated on manage_options.',
			'evidence' => 'lib/core/tests/Unit/Tool/ChatChannelGatewayToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'send_apple_message_interactive' => array(
			'class' => 'Nvoos\Core\Tool\ChatChannels\SendAppleMessageInteractiveTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the four Apple interactive widgets (Proposal 164 section 164.108): list picker, time picker, rich link and authenticate. Every correction is of one kind, a silent loss of the caller content: an over-full picker is refused where WordPress array_sliced each section to ten items and dropped the rest; a malformed section or item is refused where WordPress continued past it, so a picker could arrive with fewer choices; a time slot startTime must be an ISO 8601 instant where WordPress accepted any string; coordinates are range-checked and a duration must be positive; and a data URI must be a base64 image where WordPress forwarded any string beginning data:image/. Endpoint, envelope and the multipleSelection boolean follow the shared Apple corrections. Gated on manage_options.',
			'evidence' => 'lib/core/tests/Unit/Tool/ChatChannelGatewayToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'send_appointment_reminder' => array(
			'class' => 'Nvoos\\Core\\Tool\\Calendar\\SendAppointmentReminderTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the reminder sender (Proposal 164 section 164.88). WordPress returned success with reminder_sent false when the mail failed, ignored reminder_type while always logging email, and took hours_before through absint so any value was accepted. The port refuses sms and both because no SMS transport is bound, bounds hours_before to 1-720 and treats it as part of the reminder identity so a 24-hour and a 2-hour reminder are different sends, and records each success in _notification_log keyed by kind and revision so a retried call does not email the client twice. No calendar attachment: a reminder does not change the invitation.',
			'evidence' => 'lib/core/tests/Unit/Tool/CalendarReminderToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
		),
		'send_booking_confirmation' => array(
			'class' => 'Nvoos\\Core\\Tool\\Calendar\\SendBookingConfirmationTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the single confirmation (Proposal 164 section 164.88). WordPress declared include_ical and never read it, returned success with email_sent false when wp_mail failed, and stamped _confirmation_sent_at only on success. The port attaches an RFC 5545 invite when asked - METHOD:REQUEST with ORGANIZER and an RSVP attendee when an organizer address is supplied, METHOD:PUBLISH otherwise - returns a named email_failed error instead of a false success, renders the stored UTC times as ISO 8601, and suppresses a repeat send for the same revision unless resend is set. The capability is manage_options, which is what WordPress enforced rather than the edit_posts it advertised.',
			'evidence' => 'lib/core/tests/Unit/Tool/CalendarConfirmationToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
		),
		'send_booking_confirmations' => array(
			'class' => 'Nvoos\\Core\\Tool\\Calendar\\SendBookingConfirmationsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the batch confirmation (Proposal 164 section 164.88). WordPress read _service_type, a key no writer sets, so every preview was blank, accepted any method string so sms and both failed every row without saying why, and returned success true even when the whole batch failed. The port reads _appointment_type, refuses sms up front, bounds the batch at 50, reports already_sent per booking and returns a delivery_failed error when nothing was delivered. dry_run keeps its WordPress default of true, and the email path now carries the invite attachment.',
			'evidence' => 'lib/core/tests/Unit/Tool/CalendarConfirmationToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => true ),
		),
		'send_google_chat_message' => array(
			'class' => 'Nvoos\Core\Tool\ChatChannels\SendGoogleChatMessageTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the Chat webhook sender (Proposal 164 section 164.105). One POST of a text payload to a caller-supplied incoming webhook. Corrections: the URL must be an absolute public https endpoint, where WordPress checked only esc_url_raw and FILTER_VALIDATE_URL and would POST to http or an internal address such as the metadata service; the URL is never echoed because it carries the auth key; and a failure reports the status and provider message. Gated on manage_options.',
			'evidence' => 'lib/core/tests/Unit/Tool/ChatChannelMessengerGoogleChatToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'send_messenger_message' => array(
			'class' => 'Nvoos\Core\Tool\ChatChannels\SendMessengerMessageTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the Messenger sender (Proposal 164 section 164.105). One POST to /me/messages with the recipient PSID and a text message. Corrections: the PSID must be numeric, where WordPress passed sanitize_text_field output through, so a malformed id was a guaranteed provider error; and the reply is projected to the recipient and message id rather than the Graph document. Gated on manage_options.',
