		'send_outlook_mail' => array(
			'class' => 'Nvoos\Core\Tool\ChatChannels\SendOutlookMailTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the Outlook sender (Proposal 164 section 164.104). One POST /me/sendMail, which Graph answers 202 with no body. Corrections: an invalid CC is refused, where WordPress checked is_email and silently dropped it, so the sender believed the copy had gone; content_type is validated, where WordPress mapped anything that was not html to Text and a typo quietly sent plain text; and the reply names the recipient, CC, subject and content type rather than a bare success. is_email becomes FILTER_VALIDATE_EMAIL, which is stricter about the same shapes. Gated on manage_options.',
