		'send_reschedule_invitation' => array(
			'class' => 'Nvoos\\Core\\Tool\\Calendar\\SendRescheduleInvitationTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the no-show invitation (Proposal 164 section 164.88). WordPress gated on _appointment_status equals no_show; the toolkit writes _status with the hyphenated no-show and no writer ever set that key, so the original skipped every appointment the toolkit created. The port reads _status, accepts the underscore spelling for migrated records, refuses sms, bounds the batch at 50, suppresses repeats per revision and reports the raw status when a record is neither spelling. A batch that delivered nothing returns delivery_failed instead of success true, and the closing line asks the client to reply rather than to visit a booking page the message never linked.',
			'evidence' => 'lib/core/tests/Unit/Tool/CalendarReminderToolsTest.php',
