			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the Teams message writer (Proposal 164 section 164.104). One POST to the channel messages route with a body content payload. Corrections: the team id is validated as a GUID and the channel id validated and encoded before either becomes a path segment, where WordPress interpolated sanitize_text_field output; success is any 2xx rather than exactly 201; and the reply is the created message id, timestamp and web URL rather than the Graph document. Gated on manage_options.',
