			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the media sender (Proposal 164 section 164.103) for images, video, audio, documents and stickers, by public link or by an uploaded id. Corrections: exactly one of media_url and media_id is accepted, where WordPress preferred the id and silently ignored the URL; the link must be absolute https, where esc_url_raw accepts http; a caption the type does not support and a filename on anything but a document are refused, where WordPress dropped them silently; and an over-long caption is refused rather than truncated. Gated on manage_options.',
