			'probe' => 'call',
			'reason' => 'Ports the free-form text sender (Proposal 164 section 164.103). One POST to the phone number messages route, with the recipient normalised to E.164 (a leading plus kept, other non-digits removed) or a group JID. Corrections: preview_url is parsed rather than cast, where WordPress (bool) turned the string false into true and rendered the preview the caller refused; and the reply is the message id and normalised recipient, where WordPress returned the Graph document. The kses pass on the body is dropped because WhatsApp renders plain text anyway. Gated on manage_options.',
