		'set_availability_rules' => array(
			'class' => 'Nvoos\Core\Tool\Calendar\SetAvailabilityRulesTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the weekday rule writer (Proposal 164 section 164.83) onto SettingsStoreInterface under business_hours, keeping the WordPress enabled/start_time/end_time/slot_duration/buffer_time shape so a stored value round-trips. One call writes one weekday and leaves the other six alone; the day is replaced rather than merged, so omitted fields take the documented defaults exactly as WordPress wrote them. Corrections: clock times are validated as HH:MM, where WordPress stored any string and 9am became a rule no reader could parse; a closing time at or before the opening time is refused rather than stored as a day with no bookable slots; and the weekday is validated against the seven slugs. The settings write is wrapped, so a storage failure reports availability_write_failed instead of a fatal.',
			'evidence' => 'lib/core/tests/Unit/Tool/CalendarAvailabilityToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'sync_google_calendar' => array(
			'class' => 'Nvoos\Core\Tool\Calendar\SyncGoogleCalendarTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the outbound Google Calendar push (Proposal 164 section 164.136). The WordPress tool could never sync: it read _appointment_start, _appointment_end, _appointment_location and _appointment_customer_email, and nothing in the toolkit writes any of those four keys, so every call returned a missing-start error before reaching Google; the writers store _start_time, _end_time, _location and _client_email, and the port reads those. Three further corrections: an all-day start paired with the defaulted one-hour end emitted a mixed date/dateTime pair that Google rejects, so the pair is now consistent and the exclusive all-day end is advanced a day; send_updates externalOnly was lower-cased by sanitize_key into a value Google does not accept and silently became none, which the port matches case-insensitively; and the import directions plus a named Remote Sites connection are refused by name rather than ignored. The client refreshes the token once per instance with grant_type=refresh_token, classifies invalid_grant as a revoked credential, and keeps a 404 on update (deleted event, recreated) apart from a 404 on insert (wrong calendar). The event id is stored in _google_calendar_event_id so repeated syncs update one event.',
			'evidence' => 'lib/core/tests/Unit/Tool/CalendarGoogleSyncTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'set_cache' => array(
			'class' => 'Nvoos\\Core\\Tool\\SetCacheTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'evidence' => 'docker/laravel/app-skeleton/tests/Feature/CacheQueueAndBatchToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'set_eca_schedule' => array(
			'class' => 'Nvoos\Core\Tool\Classroom\\SetEcaScheduleTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress timetable writer over ContentStoreInterface (Proposal 164 section 164.59). Unlike WordPress, a payload whose sessions overlap each other is refused with both session numbers, and an unknown recurrence is refused rather than silently rewritten to weekly. Cross-activity venue clashes are non-blocking warnings, graded with Schedule, and the scan reads the stored session list as well as the single-slot mirror so a second session is not invisible. The first session is mirrored into the day, start, end and venue fields as WordPress does.',
			'evidence' => 'lib/core/tests/Unit/Tool/EcaWriterToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		        'shopify_catalog' => array(
		            'class' => 'Nvoos\\Core\\Tool\\Ecommerce\\ShopifyCatalogTool',
		            'readiness' => 'ready',
		            'parity' => 'port',
		            'probe' => 'call',
		            'reason' => 'Ports the WordPress catalog search (Proposal 164 section 164.121) over the keyless Universal Commerce Protocol. The endpoint was probed rather than read on 2026-11-27: tools/list and tools/call both answer 200 with no credential, and the transport is a single stateless POST, so HttpClientInterface is sufficient and no MCP client is needed. The deprecated REST catalog_api mode is dropped; the six filters it owned were re-targeted onto the UCP filters object instead of deleted (min_price and max_price as minor units, categories, shop_ids as shop GIDs, country_code as ships_to, ships_from). Five corrections: limit is no longer silently clamped to 10, price_range and variants survive the projection (the WordPress normaliser read the REST keys pricerange and minvariantprice and so emptied both against UCP), availability is the provider value rather than a fabricated true, the provider envelope is not reshaped, and description.plain is stripped of the HTML it actually carries. Nothing is cached, because UCP prohibits it.',
		            'evidence' => 'lib/core/tests/Unit/Tool/EcommerceShopifyCatalogToolTest.php',
		            'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => true ),
		        ),
		        'shopify_customers' => array(
			'class' => 'Nvoos\\Core\\Tool\\Ecommerce\\ShopifyCustomersTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress customer reader onto the Admin GraphQL API (Proposal 164 section 164.113). The store URL and token are arguments, and the URL is refused unless it is public https. The query uses only fields that survive the 2026-10 schema: defaultEmailAddress and defaultPhoneNumber replace the deprecated email and the removed phone, and addressesV2 replaces addresses; the result projects them back to email and phone so the output shape is stable.',
			'evidence' => 'lib/core/tests/Unit/Tool/EcommerceShopifyToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => true ),
		),
		'shopify_inventory' => array(
			'class' => 'Nvoos\\Core\\Tool\\Ecommerce\\ShopifyInventoryTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress inventory reader and adjuster (Proposal 164 section 164.113). Every adjustment sends changeFromQuantity, which the schema requires to be present even when null; the WordPress client omitted it, so the mutation was rejected on the current schema. expected_quantity supplies the compare-and-swap guard, a zero delta is refused before the call, and the reason is validated against the documented list.',
			'evidence' => 'lib/core/tests/Unit/Tool/EcommerceShopifyToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
