			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress order reader (Proposal 164 section 164.113). Read-only. GraphQL errors are classified once in the shared base instead of being re-checked per action, money stays the provider decimal string, and the customer reference reads defaultEmailAddress because Customer email and phone are deprecated or removed in the 2026-10 schema.',
