		'shopify_products' => array(
			'class' => 'Nvoos\\Core\\Tool\\Ecommerce\\ShopifyProductsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress product manager (Proposal 164 section 164.113), Admin API only: the deprecated REST catalog and the two keyless UCP catalog modes are a separate search tool on a separate transport. Create uses productCreate(product:) plus productVariantsBulkCreate, because ProductInput has no variants field and the input: argument is deprecated; update uses productUpdate(product:) with the id inside. Smart-search relaxation is preserved.',
			'evidence' => 'lib/core/tests/Unit/Tool/EcommerceShopifyToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'shipping_box_packer' => array(
			'class' => 'Nvoos\\Core\\Tool\\Ecommerce\\ShippingBoxPackerTool',
			'readiness' => 'pure',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress bin packer (Proposal 164 section 164.116). Pure computation: no store, credentials or network, so it is the substrate the rate estimator composes. pack_order is not ported because it reads WooCommerce line items and needs an order model. Five corrections: the USPS longest-side ceiling is 22 inches since 2026-07-12 (the original tested 18), an item must dimensionally fit a box to join its package (volume alone admitted a 20-inch item into an 8-inch box), the empty box counts towards the weight limit when the box is chosen, a malformed box list is refused instead of replaced by defaults, and cubic_eligible now agrees with cubic_tier for flat-rate boxes.',
			'evidence' => 'lib/core/tests/Unit/Tool/EcommerceShippingBoxPackerTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'shipping_rate_estimator' => array(
			'class' => 'Nvoos\\Core\\Tool\\Ecommerce\\ShippingRateEstimatorTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress rate shopper (Proposal 164 section 164.116) over the ShipStation API (formerly ShipEngine) and the legacy ShipStation API V1, both verified current on 2026-11-27. Composes BoxPacker instead of instantiating another tool. Five corrections: a run that cannot quote is a refusal rather than success with a zero total, totals are kept per currency instead of being summed across them, V1 reports shipmentCost plus otherCost (the figure it sorted by), the invented USPS/Priority Mail export rows are gone and each package reports the carrier and service the provider returned, and credentials plus the origin address are arguments rather than a plugin option, a store address or the first enabled connection. estimate_order_rates is deferred with the order model because it reads WooCommerce orders.',
			'evidence' => 'lib/core/tests/Unit/Tool/EcommerceShippingRateEstimatorTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'simplify_expression' => array(
			'class' => 'Nvoos\\Core\\Tool\\Math\\SimplifyExpressionTool',
			'readiness' => 'delegated',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the algebraic simplifier (Proposal 164 section 164.168) through MathEngineInterface over POST /api/math/simplify (mathjs). Fixes the family most serious reporting defect: when the filter was unbound WordPress fell back to a whitespace-collapsing helper and returned success true with the input unchanged as the simplified value, so 2x + 3x came back as 2x + 3x under a success envelope and a message saying it had been simplified. The port never falls back; an unavailable engine is named and an unparseable expression is a validation failure. Also: latex was set to the plain-text result, which is not LaTeX for anything with a multiplication sign or a quotient, so the port asks the engine for both spellings of one node; the rules argument is gone because default, all, collect and distribute were passed to a filter nobody implemented and are not mathjs rule names, so the standard simplification is the only behaviour that ever worked; and an unknown format is refused.',
			'evidence' => 'lib/core/tests/Unit/Tool/MathComputeToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'solve_equation' => array(
			'class' => 'Nvoos\\Core\\Tool\\Math\\SolveEquationTool',
			'readiness' => 'delegated',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the polynomial solver (Proposal 164 section 164.170) through MathEngineInterface over POST /api/math/solve. mathjs rationalize supplies coefficients in the solved variable and refuses a non-polynomial, polynomialRoot handles degrees one to three, and the companion matrix plus eigs covers every higher degree, so no new dependency is needed. Fixes the defect that made the WordPress tool unsafe to trust: with no filter registered it fell back to a regex that matched ax + b and ignored everything else, so 3x^2 + 2 = 5 was read as 3x + 2 = 5 and answered x = 1 under a success envelope with the exponent silently discarded. The port has no fallback: a non-polynomial, a second symbol, a variable that is absent from the equation, or a single equation with no equals sign is a typed refusal naming the reason. Also: the equation went through sanitize_text_field, an HTML filter applied to a grammar; the equation argument was read without isset; variable was never checked to be an identifier though every engine interpolates it into expressions; explode without a limit accepted x = 2 = 3; format_number truncated every answer to four decimals; and show_steps is omitted rather than accepted and ignored, because no implementation ever produced a step. Roots are tidied so a caller never sees 2.0000000000000004 where the answer is 2, and complex roots return as re and im pairs. Delegated rather than ready because the contract is bound by the provider and this runtime cannot honour it without oos.media_worker.url.',
			'evidence' => 'lib/core/tests/Unit/Tool/SolveEquationToolTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'destructiveHint' => false, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
