			'reason' => 'Does not fabricate a match: WordPress set trigger_matched true whenever test_data was non-empty and never read trigger.conditions anywhere in the plugin, so the dry run could report that arbitrary conditions matched arbitrary data. The port returns trigger_matched as null, conditions_evaluated as false and the stored conditions verbatim, and validates the stored definition through ruleDefinition. A supplied registration_id is looked up in the registration store instead of get_post, and a supplied event_type is compared to the trigger event as a string, labelled event_matches so it cannot be read as an evaluation. validate_actions false suppresses only the action complaints (Proposal 164 section 164.159).',
