			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the partial appointment update (Proposal 164 section 164.82). Only supplied fields change; an empty change set is a named no_changes error, and each call appends {timestamp,user_id,changes} to _change_history. Corrections: the content store edit rule is enforced where WordPress checked only manage_options; a start-only update keeps the duration instead of the old end, which could precede the new start; an end before the start is refused; the overlap query is the corrected half-open pair. A missing mail transport never fails the write.',
