			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the partial schedule update (Proposal 164 section 164.80). The re-arm rule is written into the record: an explicit timestamp wins, disabling stores 0, a consumed one-shot is not re-armed by a metadata edit, and a cadence change or re-enable arms one interval from now. Only supplied fields change; widget_defaults merges key-by-key for the same reason as configure_schedule_widget_defaults. Gated on manage_options.',
