			'probe' => 'call',
			'reason' => 'Ports the WordPress status change over ContentStoreInterface (Proposal 164 section 164.147). One status vocabulary: this tool listed display names while create and list take slugs and it passed the caller string into term_exists, so a slug here created a second term beside the seeded one; the port accepts either form and stores the term name. An unusable date is refused rather than silently skipped while reporting success. The response is the full registration row, so the status reported is the status stored.',
