			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the plan updater (Proposal 164 section 164.79). Corrections: new_tasks is appended by line surgery because the WordPress regex did not compile and replaced the stored plan with null; completed_at is stamped at 100% and cleared below (CPT parity with its own CCT); edit permission is enforced, which the WordPress tool omitted. Pinned: an out-of-range task_index is silently ignored and new tasks are appended, not merged by text.',
			'evidence' => 'lib/core/tests/Unit/Tool/OrchestrationPlanToolsTest.php',
