			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Exercised against a fake FileStoreInterface: the app FileStore reads the nvoos_files tables, which the test database does not carry (Proposal 160 section 6).',
