			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'openWorldHint' => true ),
		),
		'upload_icloud_drive_file' => array(
			'class' => 'Nvoos\Core\Tool\ChatChannels\UploadICloudDriveFileTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the iCloud Drive uploader (Proposal 164 section 164.108) as one JSON POST to a host-run gateway, because Apple publishes no third-party drive API. Corrections: a file name cannot be a path, where WordPress forwarded a value containing a separator or a dot sequence for the gateway to interpret; base64 is normalised for line breaks before the strict decode, where WordPress failed the wrapped form most encoders produce; and the content type must be a MIME type. The decoded size is reported so a caller sees what was sent; no size ceiling is invented, because the gateway owns that limit. Gated on manage_options.',
			'evidence' => 'lib/core/tests/Unit/Tool/ChatChannelGatewayToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
