		'upload_onedrive_file' => array(
			'class' => 'Nvoos\Core\Tool\ChatChannels\UploadOnedriveFileTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the OneDrive uploader (Proposal 164 section 164.104). One PUT to the drive content route whose body is the decoded file, not a JSON document. Corrections: the path rejects dot and dot-dot segments as well as encoding each part; success is any 2xx rather than exactly 200 or 201; and the reply is the created item metadata rather than the Graph document. A simple-upload size ceiling is not guessed locally: a Graph refusal carries its own message. Gated on manage_options.',
			'evidence' => 'lib/core/tests/Unit/Tool/ChatChannelGraphToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => true ),
		),
		'upscale_image_ai' => array(
			'class' => 'Nvoos\\Core\\Tool\\UpscaleImageAiTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'MediaWorkerImageProduction over the media-worker `POST /api/image/upscale` route. The slug is the WordPress slug, but no super-resolution model is involved: it resamples with a kernel and reports `method`. `model` and `denoise` are not offered because the port cannot honour them.',
			'evidence' => 'docker/laravel/app-skeleton/tests/Feature/ImageProductionToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => false ),
