		'upload_reg_document' => array(
			'class' => 'Nvoos\Core\Tool\Regulatory\\UploadRegDocumentTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress document record over ContentStoreInterface (Proposal 164 section 164.148), with one declared gap: file_data is refused rather than written, because this runtime has no media or filesystem contract that could own a file lifecycle, and the refusal names the alternative. file_url is restricted to http and https, where esc_url_raw allowed any scheme into a link. A document must attach to a product or registration that exists, and the type term keeps the caller spelling instead of the slug WordPress stored.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryDocumentToolsTest.php',
			'annotations' => array( 'readOnlyHint' => false, 'destructiveHint' => false, 'idempotentHint' => false, 'openWorldHint' => false ),
		),
		'validate_reg_product' => array(
			'class' => 'Nvoos\Core\Tool\Regulatory\\ValidateRegProductTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress product validation over ContentStoreInterface (Proposal 164 section 164.150). The declared defaults were not the actual ones: the schema promised all three checks on and the handler read them with empty(), so a bare call validated nothing and reported is_valid true — a vacuous pass in a compliance toolkit. The port applies the documented defaults and only an explicit false disables a check. A negative verdict stays a successful call, with the verdict in is_valid and status. Blank ingredient items are skipped so a trailing comma does not add an ingredient, and the chapter warning is suppressed for a code already rejected for length.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryProductValidationTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'validate_document_checklist' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\ValidateDocumentChecklistTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress document checklist over ContentStoreInterface (Proposal 164 section 164.152). The required set is lowercase slugs and a document type is stored with the caller spelling preserved, while WordPress compared them with array_diff, which is case-sensitive, so a document uploaded as LoA was reported missing while sitting in the store; the port folds case before comparing and still reports the stored spelling. The country table is unchanged: eight shared types and the LK ISO, SA CPSR and IN stability additions, selected by an upper-cased country while the response echoes what the caller wrote. An unparseable expiry date counted as expired because strtotime returns false and false is less than now; the port keeps that verdict, which is the safe direction, and names the value in unparsed_expiry_dates. A registration wins over a product when both ids are supplied, now stated in the schema. An omitted country is filled from the registration country.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryComplianceToolsTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
		'validate_inci_ingredients' => array(
			'class' => 'Nvoos\\Core\\Tool\\Regulatory\\ValidateInciIngredientsTool',
			'readiness' => 'ready',
			'parity' => 'port',
			'probe' => 'call',
			'reason' => 'Ports the WordPress INCI validator over the tool base (Proposal 164 section 164.151). The schema declared check_restrictions default true and the handler read it with empty, so the documented call skipped the restriction table entirely and a list containing Hydroquinone came back is_valid true — the same vacuous-pass fault section 164.150 fixed in validate_reg_product. The port applies the declared default and only an explicit false skips the table. An input of three commas parsed to zero ingredients and passed, so zero parsed ingredients is reported as invalid. Restrictions match by case-insensitive substring on purpose: a false positive asks for a human look, a false negative ships a banned substance. country is recorded on the result and does not select a table, as in WordPress. A restricted ingredient keeps a full naming score, so status can read mostly_valid while is_valid is false.',
			'evidence' => 'lib/core/tests/Unit/Tool/RegulatoryInciHsValidationTest.php',
			'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => true, 'openWorldHint' => false ),
		),
