		'validate_reasoning_chain_prompt' => array(
			'class' => 'Nvoos\\Core\\Tool\\ValidateReasoningChainTool',
			'readiness' => 'quarantined',
			'reason' => 'Prompt-builder stand-in: returns a prompt and performs no work. The WordPress tool with this slug is canonical.',
			'replaced_by' => 'validate_reasoning_chain',
			'annotations' => array( 'readOnlyHint' => true, 'openWorldHint' => false ),
		),
		        'validate_image_for_product' => array(
		            'class' => 'Nvoos\\Core\\Tool\\Ecommerce\\ValidateImageForProductTool',
		            'readiness' => 'ready',
		            'parity' => 'port',
		            'probe' => 'call',
		            'reason' => 'Ports the WordPress try-on image validator (Proposal 164 section 164.123) onto the completion path core already uses for analyze_image, not onto VisionInferenceInterface, which has no consumer. Two passes: a local technical check (format, size, dimensions) that refuses a bad image before any token is spent, then a vision call whose answer maps onto named checks. All nine product types keep their required and optional body parts, required parts stay critical, strict_mode still fails on warnings, and the weighted 0-100 rating with A-F grades uses the same ten weights and five thresholds. Five corrections: a remote URL input is not ported because ImageInput refuses caller-supplied hosts, response_format is unavailable on this path so the prompt asks for JSON and the parser tolerates fences and prose, unreadable dimensions are info rather than a silent pass, the emoji are gone from a summary that also feeds a machine-readable payload, and the response reports the mime type and byte count instead of echoing an image URL.',
		            'evidence' => 'lib/core/tests/Unit/Tool/ValidateImageForProductToolTest.php',
		            'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => false, 'openWorldHint' => true ),
		        ),
		        'validate_image_for_vehicle' => array(
		            'class' => 'Nvoos\\Core\\Tool\\Ecommerce\\ValidateImageForVehicleTool',
		            'readiness' => 'ready',
		            'parity' => 'port',
		            'probe' => 'call',
		            'reason' => 'Ports the WordPress vehicle estimate validator (Proposal 164 section 164.124) onto the completion path, and is the reason CompletionRequest::messages accepts an array: a coverage question is about the set, so several data URIs travel as one user turn with several image_url parts. Cleaning and repair keep their separate weight sets (vehicle detection 25 for cleaning, coverage completeness 25 for repair), their separate check builders, and the four required repair views each stay critical, so three sides of four is refused even though coverage scores 75. Recommended views never score. Four corrections: a critical technical failure refuses before the model is called rather than paying for an analysis that cannot change the verdict, an unresolvable image reference is reported instead of silently skipped, no remote URL input because ImageInput never fetches a caller-supplied host, and the capability is upload_files, which is what the original enforced in its body while declaring edit_posts.',
		            'evidence' => 'lib/core/tests/Unit/Tool/ValidateImageForVehicleToolTest.php',
		            'annotations' => array( 'readOnlyHint' => true, 'idempotentHint' => false, 'openWorldHint' => true ),
		        ),
